mapper.select:
SELECT COUNT(*)
FROM READING_SEAT_RESERVATIONS
WHERE SEAT_ID = #{seatId}
  AND STATUS IN ('USING', 'RESERVED')
  AND START_TIME  <  #{endTime}
  AND END_TIME  >  #{startTime}

SELECT COUNT(*)
FROM READING_SEAT_RESERVATIONS
WHERE MEMBER_ID = #{memberId}
  AND STATUS IN ('USING', 'RESERVED')
  AND START_TIME  <  #{endTime}
  AND END_TIME  >  #{startTime}

SELECT COUNT(*)
FROM RESERVATION_PENALTIES
WHERE MEMBER_ID = #{memberId}

mapper.update:
UPDATE READING_SEAT_RESERVATIONS
SET STATUS = 'CANCELLED'
WHERE RESERVATION_ID = #{reservationId}
  AND MEMBER_ID = #{memberId}
  AND STATUS IN ('USING', 'RESERVED')

mapper.select:
SELECT COUNT(*)
FROM MEETING_ROOM_RESERVATIONS
WHERE ROOM_ID = #{roomId}
  AND STATUS IN ('USING', 'RESERVED')
  AND START_TIME  <  #{endTime}
  AND END_TIME  >  #{startTime}

mapper.update:
UPDATE MEETING_ROOM_RESERVATIONS
SET STATUS = 'CANCELLED'
WHERE RESERVATION_ID = #{reservationId}
  AND MEMBER_ID = #{memberId}
  AND (
      (
          STATUS = 'USING'
          AND END_TIME  >  CAST(SYSTIMESTAMP AS TIMESTAMP)
      )
      OR (
          STATUS = 'RESERVED'
          AND START_TIME + INTERVAL '20' MINUTE
                 >  CAST(SYSTIMESTAMP AS TIMESTAMP)
          AND END_TIME  >  CAST(SYSTIMESTAMP AS TIMESTAMP)
      )
  )

UPDATE READING_SEAT_RESERVATIONS
SET END_TIME = #{newEndTime}
WHERE RESERVATION_ID = #{reservationId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'USING'
